import loggingimport osimport threadingimport timeimport uuidfrom datetime import datetimefrom typing import Anyimport netCDF4import pandas as pdimport pytzfrom dateutil.tz import tzlocalfrom ismn.interface import ISMN_Interfacefrom pytesmo.gpu_backend import get_gpu_backendfrom pytesmo.validation_framework.adapters import AnomalyAdapter, AnomalyClimAdapterfrom pytesmo.validation_framework.data_manager import DataManagerfrom pytesmo.validation_framework.gpu_validation import GPUBatchedValidationfrom pytesmo.validation_framework.metric_calculators import (    PairwiseIntercomparisonMetrics,    TripleCollocationMetrics,    get_dataset_names,)from pytesmo.validation_framework.metric_calculators_adapters import (    SubsetsMetricsAdapter,)from pytesmo.validation_framework.readers import CachedReaderfrom pytesmo.validation_framework.results_manager import (    netcdf_results_manager,)from pytesmo.validation_framework.temporal_matchers import (    make_combined_temporal_matcher,)from pytesmo.validation_framework.ts_cache import get_ts_cachefrom pytesmo.validation_framework.validation import Validationfrom qa4sm_reader.netcdf_transcription import Pytesmo2Qa4smResultsTranscriberfrom validator import settingsfrom validator.adapters import StabilityMetricsAdapterfrom validator.batches import create_upscaling_lutfrom validator.filters import setup_filteringfrom validator.globals import (    DEFAULT_TSW,    END_TIME,    IRREGULAR_GRIDS,    ISMN,    METADATA_TEMPLATE,    OUTPUT_FOLDER,    START_TIME,)from validator.graphics import generate_all_graphsfrom validator.models import DatasetVersion, ValidationRun, ValidationTaskfrom validator.readers import adapt_timestamp, create_readerfrom validator.utils import first_file_in__logger = logging.getLogger(__name__)def _get_actual_time_range(val_run: ValidationRun, dataset_version: DatasetVersion):    try:        vs_start = dataset_version.time_range_start        vs_start_time = datetime.strptime(vs_start, "%Y-%m-%d").date()        vs_end = dataset_version.time_range_end        vs_end_time = datetime.strptime(vs_end, "%Y-%m-%d").date()        val_start_time = val_run.interval_from.date()        val_end_time = val_run.interval_to.date()        actual_start = (            val_start_time.strftime("%Y-%m-%d")            if val_start_time > vs_start_time            else vs_start_time.strftime("%Y-%m-%d")        )        actual_end = (            val_end_time.strftime("%Y-%m-%d") if val_end_time < vs_end_time else vs_end_time.strftime("%Y-%m-%d")        )    except Exception:        # exception will arise for ISMN, and for that one we can use entire range        actual_start = START_TIME        actual_end = END_TIME    return [actual_start, actual_end]def _get_spatial_reference_reader(val_run: ValidationRun) -> tuple[Any, str, dict]:    ref_reader = create_reader(        val_run.spatial_reference_configuration.dataset,        val_run.spatial_reference_configuration.version,    )    time_adapted_ref_reader = adapt_timestamp(        ref_reader,        val_run.spatial_reference_configuration.dataset,        val_run.spatial_reference_configuration.version,    )    # we do the dance with the filtering below because filter may actually    # change the original reader, see ismn network selection    filtered_reader, read_name, read_kwargs = setup_filtering(        reader=time_adapted_ref_reader,        filters=list(val_run.spatial_reference_configuration.filters),        param_filters=list(val_run.spatial_reference_configuration.parametrised_filters),        dataset=val_run.spatial_reference_configuration.dataset,        variable=val_run.spatial_reference_configuration.variable,    )    while hasattr(ref_reader, "cls"):        ref_reader = ref_reader.cls    return ref_reader, read_name, read_kwargsdef set_outfile(validation_run: ValidationRun, run_dir: str):    outfile = first_file_in(run_dir, ".nc")    if outfile is not None:        out_norm = os.path.normpath(outfile)        root_norm = os.path.normpath(OUTPUT_FOLDER)        if os.path.isabs(out_norm):            try:                in_output_root = os.path.commonpath([out_norm, root_norm]) == root_norm            except ValueError:                in_output_root = False            if in_output_root:                out_norm = os.path.relpath(out_norm, root_norm)            else:                out_norm = os.path.basename(out_norm)        validation_run.output_file = out_normdef save_validation_config(validation_run: ValidationRun):    try:        with netCDF4.Dataset(            os.path.join(OUTPUT_FOLDER, validation_run.output_file),            "a",            format="NETCDF4",        ) as ds:            try:                if hasattr(validation_run, "spatial_reference_configuration"):                    dataset = validation_run.spatial_reference_configuration.dataset                    if dataset and hasattr(dataset, "is_scattered_data"):                        ds.val_is_scattered_data = str(dataset.is_scattered_data)            except (AttributeError, TypeError):                pass            if validation_run.interval_from is None:                ds.val_interval_from = "N/A"            else:                ds.val_interval_from = validation_run.interval_from.strftime("%Y-%m-%d %H:%M")            if validation_run.interval_to is None:                ds.val_interval_to = "N/A"            else:                ds.val_interval_to = validation_run.interval_to.strftime("%Y-%m-%d %H:%M")            j = 1            for dataset_config in validation_run.dataset_configurations:                filters = None                if dataset_config.filters:                    filters = "; ".join([x.description for x in dataset_config.filters])                if dataset_config.parametrised_filters:                    if filters:                        filters += ";"                    _list_comp = [                        pf.filter.description + " " + pf.parameters for pf in dataset_config.parametrised_filters                    ]                    try:                        filters += "; ".join(_list_comp)                    except TypeError as e:                        __logger.error(f"Error in save_validation_config: {e}. {filters=}{_list_comp=}")                        filters = "; ".join(_list_comp)                if not filters:                    filters = "N/A"                if validation_run.spatial_reference_configuration and (                    dataset_config.id == validation_run.spatial_reference_configuration.id                ):                    i = 0  # reference is always 0                else:                    i = j                    j += 1                # there is no error for variables!!, there were some inconsistency with short and pretty names,                # and it should be like that now                ds.setncattr("val_dc_dataset" + str(i), dataset_config.dataset.short_name)                ds.setncattr("val_dc_version" + str(i), dataset_config.version.short_name)                ds.setncattr("val_dc_variable" + str(i), dataset_config.variable.pretty_name)                ds.setncattr("val_dc_unit" + str(i), dataset_config.variable.unit)                ds.setncattr(                    "val_dc_dataset_pretty_name" + str(i),                    dataset_config.dataset.pretty_name,                )                ds.setncattr(                    "val_dc_version_pretty_name" + str(i),                    dataset_config.version.pretty_name,                )                ds.setncattr(                    "val_dc_variable_pretty_name" + str(i),                    dataset_config.variable.short_name,                )                ds.setncattr("val_dc_filters" + str(i), filters)                actual_interval_from, actual_interval_to = _get_actual_time_range(                    validation_run, dataset_config.version.id                )                ds.setncattr("val_dc_actual_interval_from" + str(i), actual_interval_from)                ds.setncattr("val_dc_actual_interval_to" + str(i), actual_interval_to)                if (validation_run.spatial_reference_configuration is not None) and (                    dataset_config.id == validation_run.spatial_reference_configuration.id                ):                    ds.val_ref = "val_dc_dataset" + str(i)                    try:                        ds.setncattr(                            "val_resolution",                            validation_run.spatial_reference_configuration.dataset.resolution["value"],                        )                        ds.setncattr(                            "val_resolution_unit",                            validation_run.spatial_reference_configuration.dataset.resolution["unit"],                        )                    # ISMN has null resolution attribute, therefore                    # we write no output resolution                    # same is true for user datasets                    except (AttributeError, TypeError):                        pass                if (validation_run.scaling_ref is not None) and (dataset_config.id == validation_run.scaling_ref.id):                    ds.val_scaling_ref = "val_dc_dataset" + str(i)                if dataset_config.dataset.short_name in IRREGULAR_GRIDS.keys():                    grid_stepsize = IRREGULAR_GRIDS[dataset_config.dataset.short_name]                else:                    grid_stepsize = "nan"                ds.setncattr("val_dc_dataset" + str(i) + "_grid_stepsize", grid_stepsize)            ds.val_scaling_method = validation_run.scaling_method            ds.val_anomalies = validation_run.anomalies            if validation_run.anomalies == ValidationRun.CLIMATOLOGY:                ds.val_anomalies_from = validation_run.anomalies_from.strftime("%Y-%m-%d %H:%M")                ds.val_anomalies_to = validation_run.anomalies_to.strftime("%Y-%m-%d %H:%M")            if all(                x is not None                for x in [                    validation_run.min_lat,                    validation_run.min_lon,                    validation_run.max_lat,                    validation_run.max_lon,                ]            ):                ds.val_spatial_subset = (                    f"[{validation_run.min_lat}, {validation_run.min_lon}, "                    f"{validation_run.max_lat}, {validation_run.max_lon}]"                )    except Exception:        __logger.exception("Validation configuration could not be stored.")def _apply_anomaly_adapter(reader, validation_run, dataset_config, read_name):    if validation_run.anomalies == ValidationRun.MOVING_AVG_35_D:        return AnomalyAdapter(            reader,            window_size=35,            columns=[dataset_config.variable.short_name],            read_name=read_name,        )    if validation_run.anomalies == ValidationRun.CLIMATOLOGY:        anomalies_baseline = [            validation_run.anomalies_from.astimezone(tz=pytz.UTC).replace(tzinfo=None),            validation_run.anomalies_to.astimezone(tz=pytz.UTC).replace(tzinfo=None),        ]        return AnomalyClimAdapter(            reader,            columns=[dataset_config.variable.short_name],            timespan=anomalies_baseline,            read_name=read_name,        )    return readerdef _setup_metric_calculators(    ds_num, ds_names, validation_run, metadata_template, temp_sub_wdws, temp_sub_wdw_instance, spatial_ref_name=None):    _pairwise_metrics = PairwiseIntercomparisonMetrics(        metadata_template=metadata_template,        calc_kendall=False,    )    if validation_run.intra_annual_metrics and validation_run.stability_metrics:        raise ValueError("Both intra_annual_metrics and stability_metrics cannot be True at the same time.")    tsw_metrics = None    if validation_run.intra_annual_metrics:        tsw_metrics = "intra_annual"    elif validation_run.stability_metrics:        tsw_metrics = "stability"    if tsw_metrics:        if isinstance(temp_sub_wdws, dict):            adapter_cls = StabilityMetricsAdapter if tsw_metrics == "stability" else SubsetsMetricsAdapter            pairwise_metrics = adapter_cls(                calculator=_pairwise_metrics,                subsets=temp_sub_wdw_instance.custom_temporal_sub_windows,                group_results="join",            )    else:        pairwise_metrics = _pairwise_metrics    metric_calculators = {(ds_num, 2): pairwise_metrics.calc_metrics}    if (len(ds_names) >= 3) and (validation_run.tcol is True):        _tcol_metrics = TripleCollocationMetrics(            spatial_ref_name or validation_run.spatial_reference_configuration.dataset.short_name,            metadata_template=metadata_template,            bootstrap_cis=validation_run.bootstrap_tcol_cis,        )        if isinstance(temp_sub_wdws, dict):            tcol_metrics = SubsetsMetricsAdapter(                calculator=_tcol_metrics,                subsets=temp_sub_wdw_instance.custom_temporal_sub_windows,                group_results="join",            )        elif temp_sub_wdws is None:            tcol_metrics = _tcol_metrics        metric_calculators.update({(ds_num, 3): tcol_metrics.calc_metrics})    return metric_calculatorsdef _setup_upscaling(validation_run, datasets, spatial_ref_name):    if validation_run.upscaling_method == "none":        return None    upscale_parms = {        "upscaling_method": validation_run.upscaling_method,        "temporal_stability": validation_run.temporal_stability,    }    upscale_parms["upscaling_lut"] = create_upscaling_lut(        validation_run=validation_run,        datasets=datasets,        spatial_ref_name=spatial_ref_name,    )    return upscale_parmsdef create_pytesmo_validation(validation_run: ValidationRun):    ds_list = []    ds_read_names = []    spatial_ref_name = None    scaling_ref_name = None    temporal_ref_name = None    spatial_ref_short_name = None    ds_num = 1    for dataset_config in validation_run.dataset_configurations:        reader = create_reader(dataset_config.dataset, dataset_config.version)        time_adapted_reader = adapt_timestamp(reader, dataset_config.dataset, dataset_config.version)        reader, read_name, read_kwargs = setup_filtering(            reader=time_adapted_reader,            filters=list(dataset_config.filters),            param_filters=list(dataset_config.parametrised_filters),            dataset=dataset_config.dataset,            variable=dataset_config.variable,        )        reader = _apply_anomaly_adapter(reader, validation_run, dataset_config, read_name)        is_spatial_ref = (            validation_run.spatial_reference_configuration            and dataset_config.id == validation_run.spatial_reference_configuration.id        )        dataset_name = (            f"0-{dataset_config.dataset.short_name}"            if is_spatial_ref            else f"{ds_num}-{dataset_config.dataset.short_name}"        )        if not is_spatial_ref:            ds_num += 1        ds_list.append(            (                dataset_name,                {                    "class": reader,                    "columns": [dataset_config.variable.short_name],                    "kwargs": read_kwargs,                    "max_dist": dataset_config.dataset.resolution_in_m,                },            )        )        ds_read_names.append((dataset_name, read_name))        if is_spatial_ref:            spatial_ref_name = dataset_name            spatial_ref_short_name = dataset_config.dataset.short_name        if validation_run.scaling_ref and dataset_config.id == validation_run.scaling_ref.id:            scaling_ref_name = dataset_name        if (            validation_run.temporal_reference_configuration            and dataset_config.id == validation_run.temporal_reference_configuration.id        ):            temporal_ref_name = dataset_name    datasets = dict(ds_list)    ds_num = len(ds_list)    period = get_period(validation_run)  # noqa: F821    upscale_parms = _setup_upscaling(validation_run, datasets, spatial_ref_name)    datamanager = DataManager(        datasets,        ref_name=spatial_ref_name,        period=period,        read_ts_names=dict(ds_read_names),        upscale_parms=upscale_parms,    )    ds_names = get_dataset_names(datamanager.reference_name, datamanager.datasets, n=ds_num)    metadata_template = METADATA_TEMPLATE["ismn_ref" if spatial_ref_short_name == ISMN else "other_ref"]    tsw_dict = define_tsw_metrics(validation_run, period)  # noqa: F821    temp_sub_wdw_instance = tsw_dict["temp_sub_wdw_instance"]    temp_sub_wdws = tsw_dict["temp_sub_wdws"]    metric_calculators = _setup_metric_calculators(        ds_num,        ds_names,        validation_run,        metadata_template,        temp_sub_wdws,        temp_sub_wdw_instance,        spatial_ref_name=spatial_ref_name,    )    scaling_method = (        None if validation_run.scaling_method == validation_run.NO_SCALING else validation_run.scaling_method    )    temporalwindow_size = validation_run.temporal_matching    val = Validation(        datasets=datamanager,        temporal_matcher=make_combined_temporal_matcher(pd.Timedelta(temporalwindow_size / 2, "h")),        temporal_ref=temporal_ref_name,        spatial_ref=spatial_ref_name,        scaling=scaling_method,        scaling_ref=scaling_ref_name,        metrics_calculators=metric_calculators,        period=period,    )    return valdef num_gpis_from_job(job):    try:        num_gpis = len(job[0])    except Exception:        num_gpis = 1    return num_gpisdef execute_job(validation_run, job, task_id=None, max_retries=1, retry_delay_seconds=1):    if task_id is None:        task_id = uuid.uuid4().hex    numgpis = num_gpis_from_job(job)    for attempt in range(max_retries + 1):        __logger.debug(            f"Executing job {task_id} from validation {validation_run.id}, "            f"# of gpis: {numgpis}, attempt {attempt + 1}/{max_retries + 1}"        )        start_time = datetime.now(tzlocal())        try:            val = create_pytesmo_validation(validation_run)            result = val.calc(                *job,                rename_cols=False,                only_with_reference=True,                handle_errors="ignore",            )            end_time = datetime.now(tzlocal())            duration = end_time - start_time            duration = (duration.days * 86400) + duration.seconds            __logger.debug(                f"Finished job {task_id} from validation {validation_run.id}, "                f"took {duration} seconds for {numgpis} gpis"            )            return result        except Exception as e:            # Handle non-retriable KeyError cases (missing DataFrame columns)            if isinstance(e, KeyError) and str(e).strip("'") in {"gpi", "frm_class", "status"}:                __logger.warning(                    f"Job {task_id} from validation {validation_run.id} hit non-retriable key error {e}. "                    "Marking job as empty result and continuing."                )                return {}            # Handle pytesmo TripleCollocationMetrics bug with empty DataFrames            if isinstance(e, ValueError) and "list.remove(x): x not in list" in str(e):                __logger.warning(                    "Job %s hit pytesmo tcol bug (empty DataFrame for dummy result). Returning empty result.",                    task_id,                )                return {}            if attempt < max_retries:                __logger.warning(                    "Job %s failed on attempt %s/%s (%s: %s). Retrying in %ss.",                    task_id,                    attempt + 1,                    max_retries + 1,                    type(e).__name__,                    str(e)[:120],                    retry_delay_seconds,                )                time.sleep(retry_delay_seconds)                continue            raisedef check_and_store_results(job_id, results, save_path):    if len(results) < 1:        __logger.warning(f"Potentially problematic job: {job_id} - no results")        return    try:        netcdf_results_manager(results, save_path)    except OSError as exc:        # A stale/corrupted nc file from a previous interrupted run can break appends.        msg = str(exc)        recoverable = "NetCDF: Unknown file format" in msg or "NetCDF: Write to read only" in msg        if not recoverable:            raise        bad_file = None        for token in msg.split("'"):            if token.lower().endswith(".nc"):                bad_file = token                break        if bad_file and os.path.exists(bad_file):            __logger.warning(                "Detected corrupted netCDF result file for job %s. Removing %s and retrying write once.",                job_id,                bad_file,            )            os.remove(bad_file)            netcdf_results_manager(results, save_path)            return        raisedef track_validation_task(validation_run, task_id):    validation_task = ValidationTask()    validation_task.validation = validation_run    validation_task.task_id = uuid.UUID(task_id).hex    validation_task.save()def validation_task_cancelled(task_id):    # stop_running_validation deletes the validation task records.    # If they don't exist anymore, this task is treated as cancelled.    return not ValidationTask.objects.filter(task_id=task_id).exists()def untrack_validation_task(task_id):    try:        validation_task = ValidationTask.objects.get(task_id=task_id)        validation_task.delete()    except ValidationTask.DoesNotExist:        __logger.debug(f"Task {task_id} already deleted from db.")def _count_job_status(results: dict, ngpis: int) -> tuple[int, int]:    result_key = list(results.keys())[0]    res = results[result_key]    status_keys = [s for s in res if "status" in s and not s.split("|")[0].isdigit()]    ok = res[status_keys[0]] == 0    for sk in status_keys[1:]:        ok = ok & (res[sk] == 0)    nok = sum(ok)    return nok, ngpis - nokdef _process_job_result(task_id, future, job_table, validation_run, run_dir):    results = future.result()    if not results:        validation_run.error_points += num_gpis_from_job(job_table[task_id])        return None    results = _pytesmo_to_qa4sm_results(results)  # noqa: F821    check_and_store_results(task_id, results, run_dir)    ngpis = num_gpis_from_job(job_table[task_id])    ok_pts, error_pts = _count_job_status(results, ngpis)    validation_run.ok_points += ok_pts    validation_run.error_points += error_pts    return resultsdef _post_process_run(validation_run, run_dir, results):    set_outfile(validation_run, run_dir)    iam_dict = define_tsw_metrics(validation_run, get_period(validation_run))  # noqa: F821    temp_sub_wdw_instance = iam_dict["temp_sub_wdw_instance"]    temp_sub_wdws = iam_dict["temp_sub_wdws"]    transcriber = Pytesmo2Qa4smResultsTranscriber(        pytesmo_results=os.path.join(OUTPUT_FOLDER, validation_run.output_file),        intra_annual_slices=temp_sub_wdw_instance,        keep_pytesmo_ncfile=False,    )    if not transcriber.exists:        return    _outname, outname_zarr = transcriber.build_outname(run_dir, results.keys())    transcriber.output_file_name = str(_outname)    transcriber.output_zarr_name = str(outname_zarr)    # Initialize transcribed_dataset before writing — write_to_netcdf relies on    # self.transcribed_dataset which is only populated by get_transcribed_dataset()    transcriber.get_transcribed_dataset()    transcriber.write_to_netcdf(transcriber.output_file_name)    save_validation_config(validation_run)    transcriber.compress(path=transcriber.output_file_name, compression="zlib", complevel=9)    temporal_sub_windows_names = [DEFAULT_TSW] if temp_sub_wdws is None else temp_sub_wdw_instance.names    __logger.info(f"temporal_sub_windows_names: {temporal_sub_windows_names}")    generate_all_graphs(        validation_run=validation_run,        outfolder=run_dir,        temporal_sub_windows=temporal_sub_windows_names,        save_metadata=validation_run.plots_save_metadata,    )def _clear_stale_outputs(run_dir):    stale = [os.path.join(run_dir, name) for name in os.listdir(run_dir) if name.endswith(".nc")]    if not stale:        return    for nc_file in stale:        try:            os.remove(nc_file)        except OSError:            __logger.warning("Could not remove stale netCDF file %s", nc_file)    __logger.info(        "Removed %s stale netCDF file(s) from %s before starting validation.",        len(stale),        run_dir,    )def _determine_max_workers(jobs, ref_reader):    configured = getattr(settings, "MAX_PARALLEL_WORKERS", os.cpu_count() or 1)    max_workers = max(1, min(len(jobs), configured))    if isinstance(ref_reader, ISMN_Interface) and max_workers > 1:        __logger.warning("ISMN reference reader is not safe for threaded execution. Forcing max_workers=1.")        max_workers = 1    return max_workers_thread_local = threading.local()def _get_worker_validation(validation_run: ValidationRun, use_gpu: bool = False):    """Get or create a per-thread validation object."""    cache = getattr(_thread_local, "validation", None)    cache_id = cache.get("validation_run_id")    if cache is not None and cache_id == str(validation_run.id) and cache.get("use_gpu") == use_gpu:        return cache["val"]    if use_gpu:        from pytesmo.gpu_backend import get_gpu_backend        from validator.settings import GPU_DEVICE_ID        device_id = validation_run.gpu_device_id if validation_run.gpu_device_id else GPU_DEVICE_ID        get_gpu_backend(device_id=device_id)        val = _create_validation(validation_run, use_gpu=True)    else:        val = _create_validation(validation_run, use_gpu=False)    _thread_local.validation = {"validation_run_id": str(validation_run.id), "use_gpu": use_gpu, "val": val}    return valdef _create_validation(validation_run: ValidationRun, use_gpu: bool = False):    if use_gpu:        return _create_gpu_validation(validation_run)    return create_pytesmo_validation(validation_run)def _create_gpu_validation(validation_run: ValidationRun):
    import pandas as pd    from pytesmo.validation_framework.data_manager import DataManager    from pytesmo.validation_framework.metric_calculators import (        get_dataset_names,    )    from pytesmo.validation_framework.temporal_matchers import (        make_combined_temporal_matcher,    )    from validator.filters import setup_filtering    from validator.globals import (        ISMN,        METADATA_TEMPLATE,    )    from validator.readers import adapt_timestamp, create_reader    from validator.settings import GPU_BATCH_SIZE, GPU_DEVICE_ID    from validator.utils import get_period    from validator.validation import define_tsw_metrics
    # Ensure GPU backend is initialized for this device
    device_id = validation_run.gpu_device_id if validation_run.gpu_device_id else GPU_DEVICE_ID
    get_gpu_backend(device_id=device_id)

    ds_list = []
    ds_read_names = []
    spatial_ref_name = None
    scaling_ref_name = None
    temporal_ref_name = None
    spatial_ref_short_name = None
    dataset_short_names = []

    ds_num = 1
    for dataset_config in validation_run.dataset_configurations:
        reader = create_reader(dataset_config.dataset, dataset_config.version)
        time_adapted_reader = adapt_timestamp(reader, dataset_config.dataset, dataset_config.version)
        reader, read_name, read_kwargs = setup_filtering(
            reader=time_adapted_reader,
            filters=list(dataset_config.filters),
            param_filters=list(dataset_config.parametrised_filters),
            dataset=dataset_config.dataset,
            variable=dataset_config.variable,
        )
        reader = _apply_anomaly_adapter(reader, validation_run, dataset_config, read_name)

        is_spatial_ref = (
            validation_run.spatial_reference_configuration
            and dataset_config.id == validation_run.spatial_reference_configuration.id
        )
        dataset_name = (
            f"0-{dataset_config.dataset.short_name}"
            if is_spatial_ref
            else f"{ds_num}-{dataset_config.dataset.short_name}"
        )
        if not is_spatial_ref:
            ds_num += 1

        if get_ts_cache().max_size_bytes > 0:
            reader = CachedReader(reader)

        ds_list.append(
            (
                dataset_name,
                {
                    "class": reader,
                    "columns": [dataset_config.variable.short_name],
                    "kwargs": read_kwargs,
                    "max_dist": dataset_config.dataset.resolution_in_m,
                },
            )
        )
        ds_read_names.append((dataset_name, read_name))
        dataset_short_names.append(dataset_config.dataset.short_name)

        if is_spatial_ref:
            spatial_ref_name = dataset_name
            spatial_ref_short_name = dataset_config.dataset.short_name
        if validation_run.scaling_ref and dataset_config.id == validation_run.scaling_ref.id:
            scaling_ref_name = dataset_name
        if (
            validation_run.temporal_reference_configuration
            and dataset_config.id == validation_run.temporal_reference_configuration.id
        ):
            temporal_ref_name = dataset_name

    datasets = dict(ds_list)
    ds_num = len(ds_list)
    period = get_period(validation_run)  # noqa: F821

    upscale_parms = _setup_upscaling(validation_run, datasets, spatial_ref_name)

    datamanager = DataManager(
        datasets,
        ref_name=spatial_ref_name,
        period=period,
        read_ts_names=dict(ds_read_names),
        upscale_parms=upscale_parms,
    )
    ds_names = get_dataset_names(datamanager.reference_name, datamanager.datasets, n=ds_num)

    metadata_template = METADATA_TEMPLATE["ismn_ref" if spatial_ref_short_name == ISMN else "other_ref"]

    tsw_dict = define_tsw_metrics(validation_run, period)  # noqa: F821
    temp_sub_wdw_instance = tsw_dict["temp_sub_wdw_instance"]
    temp_sub_wdws = tsw_dict["temp_sub_wdws"]

    metric_calculators = _setup_metric_calculators(
        ds_num,
        ds_names,
        validation_run,
        metadata_template,
        temp_sub_wdws,
        temp_sub_wdw_instance,
        spatial_ref_name=spatial_ref_name,
    )

    scaling_method = (
        None if validation_run.scaling_method == validation_run.NO_SCALING else validation_run.scaling_method
    )
    temporalwindow_size = validation_run.temporal_matching

    gpu_val = GPUBatchedValidation(
        datamanager=datamanager,
        temporal_matcher=make_combined_temporal_matcher(pd.Timedelta(temporalwindow_size / 2, "h")),
        temporal_ref=temporal_ref_name,
        spatial_ref=spatial_ref_name,
        scaling=scaling_method,
        scaling_ref=scaling_ref_name,
        metrics_calculators=metric_calculators,
        batch_size=getattr(validation_run, "batch_size", None) or GPU_BATCH_SIZE,
    )
    return gpu_val


